spec.compute:
var n1 = +s.n1 || 0, n2 = +s.n2 || 0, n3 = +s.n3 || 0, n4 = +s.n4 || 0, n5 = +s.n5 || 0, n6 = +s.n6 || 0;
var n = n1 + n2 + n3 + n4 + n5 + n6;
if (n === 0) {
  return { n_tot: 0, mean: 0, var: 0, sd: 0, iv_low: 0, iv_high: 0 };
}
var sum_prod = (1*n1) + (2*n2) + (3*n3) + (4*n4) + (5*n5) + (6*n6);
var mean = sum_prod / n;
var sum_sq = (Math.pow(1 - mean, 2) * n1) +
             (Math.pow(2 - mean, 2) * n2) +
             (Math.pow(3 - mean, 2) * n3) +
             (Math.pow(4 - mean, 2) * n4) +
             (Math.pow(5 - mean, 2) * n5) +
             (Math.pow(6 - mean, 2) * n6);
var variance = sum_sq / n;
var sd = Math.sqrt(variance);
return {
  n_tot: n,
  mean: mean,
  var: variance,
  sd: sd,
  iv_low: Math.max(1, mean - sd),
  iv_high: Math.min(6, mean + sd)
};

spec.render:
var maxVal = Math.max(1, s.n1, s.n2, s.n3, s.n4, s.n5, s.n6);
var scale = 160 / maxVal;
var baseY = 250;
var counts = [s.n1, s.n2, s.n3, s.n4, s.n5, s.n6];
for (var i = 1; i <= 6; i++) {
  var val = counts[i - 1] || 0;
  var barH = val * scale;
  var barY = baseY - barH;
  var barEl = root.querySelector('#bar_' + i);
  var txtEl = root.querySelector('#txt_' + i);
  if (barEl) {
    barEl.setAttribute('y', barY);
    barEl.setAttribute('height', Math.max(0, barH));
  }
  if (txtEl) {
    txtEl.setAttribute('y', Math.max(68, barY - 6));
    txtEl.textContent = val;
  }
}
function noteToX(val) {
  return 80 + (val - 1) * 80;
}
var meanX = noteToX(o.mean || 1);
var meanLine = root.querySelector('#sim_mean_line');
var meanDot = root.querySelector('#sim_mean_dot');
var meanTxt = root.querySelector('#sim_mean_text');
if (meanLine) {
  meanLine.setAttribute('x1', meanX);
  meanLine.setAttribute('x2', meanX);
}
if (meanDot) {
  meanDot.setAttribute('cx', meanX);
}
if (meanTxt) {
  meanTxt.setAttribute('x', meanX);
  meanTxt.textContent = 'x̄ = ' + (typeof o.mean === 'number' ? o.mean.toFixed(2) : o.mean);
}
var lowX = noteToX(Math.max(1, o.iv_low || 1));
var highX = noteToX(Math.min(6, o.iv_high || 6));
var ivBox = root.querySelector('#sim_iv_box');
var ivTxt = root.querySelector('#sim_iv_label');
var ivBg = root.querySelector('#sim_iv_bg');
var midX = (lowX + highX) / 2;
var badgeW = 120;
if (ivBox) {
  ivBox.setAttribute('x', lowX);
  ivBox.setAttribute('width', Math.max(6, highX - lowX));
}
if (ivBg) {
  ivBg.setAttribute('x', midX - badgeW / 2);
  ivBg.setAttribute('width', badgeW);
}
if (ivTxt) {
  ivTxt.setAttribute('x', midX);
  ivTxt.textContent = '[' + (o.iv_low ? o.iv_low.toFixed(2) : '1.00') + ' ; ' + (o.iv_high ? o.iv_high.toFixed(2) : '6.00') + ']';
}
